1	"use client";
2	
3	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
4	import { Badge } from "@/components/ui/primitives";
5	import {
6	  ensureDbManager,
7	  dbmgrStatus,
8	  dbmgrListDatabases,
9	  dbmgrTableCounts,
10	  dbmgrDatabaseOverview,
11	  dbmgrBrowseTable,
12	  dbmgrRunSql,
13	  dbmgrTableStructure,
14	  dbmgrInsertRow,
15	  dbmgrUpdateRow,
16	  dbmgrDeleteRow,
17	  dbmgrExportTable,
18	  dbmgrImportSql,
19	  dbmgrTruncateTable,
20	  dbmgrDropTable,
21	  dbmgrRenameTable,
22	  dbmgrMaintainTable,
23	  dbmgrAddColumn,
24	  dbmgrDropColumn,
25	  dbmgrAddIndex,
26	  dbmgrDropIndex,
27	  type DbMgrDatabase,
28	  type DbMgrTableInfo,
29	  type DbMgrOverviewTable,
30	  type DbMgrStructure,
31	  type DbMgrColumn,
32	  type DbMgrFilter,
33	  type DbCellValue,
34	} from "@/lib/actions-hosting-db";
35	
36	/**
37	 * Nxeon DB Studio — the PROPRIETARY, in-portal database manager (a phpMyAdmin-class
38	 * experience with the Nxeon design system). Every action runs SERVER-SIDE as the
39	 * account's scoped `<username>_mgr` MySQL user over an SSH-tunnelled mysql2 session
40	 * (see lib/hosting-db.ts): the browser never holds a DB credential and the grant is
41	 * the isolation boundary, so it can only ever touch this account's own databases.
42	 */
43	export function DbManager({ accountId }: { accountId: string }) {
44	  const [status, setStatus] = useState<"loading" | "provisioning" | "ready" | "error">("loading");
45	  const [statusMsg, setStatusMsg] = useState("");
46	  const [databases, setDatabases] = useState<DbMgrDatabase[]>([]);
47	  const [activeDb, setActiveDb] = useState<string>("");
48	  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);
49	
50	  useEffect(() => {
51	    let cancelled = false;
52	    (async () => {
53	      const [ens, list] = await Promise.all([ensureDbManager(accountId), dbmgrListDatabases(accountId)]);
54	      if (cancelled) return;
55	      if (list.databases) {
56	        setDatabases(list.databases);
57	        const firstActive = list.databases.find((d) => d.status === "ACTIVE") ?? list.databases[0];
58	        if (firstActive) setActiveDb(firstActive.name);
59	      }
60	      if (ens.error) { setStatus("error"); setStatusMsg(ens.error); return; }
61	      if (ens.ready) { setStatus("ready"); return; }
62	      setStatus("provisioning");
63	    })();
64	    return () => { cancelled = true; };
65	  }, [accountId]);
66	
67	  useEffect(() => {
68	    if (status !== "provisioning") return;
69	    let tries = 0;
70	    pollRef.current = setInterval(async () => {
71	      tries++;
72	      const s = await dbmgrStatus(accountId);
73	      if (s.ready) { setStatus("ready"); if (pollRef.current) clearInterval(pollRef.current); return; }
74	      if (tries >= 20) { setStatus("error"); setStatusMsg("The database manager is taking longer than expected to set up. Try again shortly."); if (pollRef.current) clearInterval(pollRef.current); }
75	    }, 3000);
76	    return () => { if (pollRef.current) clearInterval(pollRef.current); };
77	  }, [status, accountId]);
78	
79	  const activeDbs = databases.filter((d) => d.status === "ACTIVE");
80	
81	  return (
82	    <div className="overflow-hidden rounded-2xl border border-white/[0.07] bg-navy-900/60 backdrop-blur-md">
83	      {/* Studio header */}
84	      <div className="flex flex-wrap items-center justify-between gap-3 border-b border-white/[0.06] bg-gradient-to-r from-accent-blue/[0.08] to-brand-500/[0.06] px-4 py-3">
85	        <div className="flex items-center gap-2.5">
86	          <span className="grid h-9 w-9 flex-none place-items-center rounded-xl bg-gradient-to-br from-accent-blue to-brand-500 text-white shadow-[0_0_22px_-4px_rgb(111_71_245_/_0.6)]">
87	            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
88	              <ellipse cx="12" cy="5" rx="8" ry="3" />
89	              <path d="M4 5v6c0 1.7 3.6 3 8 3s8-1.3 8-3V5M4 11v6c0 1.7 3.6 3 8 3s8-1.3 8-3v-6" />
90	            </svg>
91	          </span>
92	          <div className="flex flex-col gap-0.5">
93	            <span className="text-[15px] font-bold leading-none tracking-tight text-white">
94	              Nxeon <span className="grad-text">DB Studio</span>
95	            </span>
96	            <p className="text-[11px] text-slate-500">Browse, query &amp; edit your databases</p>
97	          </div>
98	        </div>
99	        <div className="flex items-center gap-2">
100	          {status === "ready" && <Badge tone="green">connected</Badge>}
101	          {status === "provisioning" && <Badge tone="amber">preparing</Badge>}
102	          {status === "error" && <Badge tone="red">unavailable</Badge>}
103	        </div>
104	      </div>
105	
106	      <div className="p-4">
107	        {status === "loading" && <SkeletonStudio />}
108	        {status === "provisioning" && (
109	          <div className="flex items-center gap-3 rounded-xl border border-amber-500/20 bg-amber-500/[0.06] px-4 py-3">
110	            <Spinner />
111	            <p className="text-xs text-amber-200">Preparing your secure database connection… this only happens once.</p>
112	          </div>
113	        )}
114	        {status === "error" && (
115	          <div className="rounded-xl border border-red-500/20 bg-red-500/[0.06] px-4 py-3 text-xs text-red-200">{statusMsg || "The database manager is unavailable right now."}</div>
116	        )}
117	
118	        {status === "ready" && databases.length === 0 && (
119	          <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-10 text-center">
120	            <DatabaseIcon className="mx-auto mb-3 h-8 w-8 text-brand-300/70" />
121	            <p className="text-sm font-medium text-slate-200">No databases yet</p>
122	            <p className="mx-auto mt-1 max-w-sm text-xs text-slate-500">Create your first database below, then come back to browse tables, run queries and edit rows here.</p>
123	          </div>
124	        )}
125	
126	        {status === "ready" && databases.length > 0 && (
127	          <Studio
128	            key={activeDb}
129	            accountId={accountId}
130	            databases={databases}
131	            activeDbs={activeDbs}
132	            activeDb={activeDb}
133	            onPickDb={setActiveDb}
134	          />
135	        )}
136	      </div>
137	    </div>
138	  );
139	}
140	
141	/* ================================================================= Studio === */
142	
143	type MainTab = "overview" | "browse" | "structure" | "sql" | "import";
144	
145	function Studio({
146	  accountId,
147	  databases,
148	  activeDbs,
149	  activeDb,
150	  onPickDb,
151	}: {
152	  accountId: string;
153	  databases: DbMgrDatabase[];
154	  activeDbs: DbMgrDatabase[];
155	  activeDb: string;
156	  onPickDb: (db: string) => void;
157	}) {
158	  const [tables, setTables] = useState<DbMgrTableInfo[]>([]);
159	  const [tablesErr, setTablesErr] = useState("");
160	  const [tablesBusy, setTablesBusy] = useState(true);
161	  const [filter, setFilter] = useState("");
162	  const [activeTable, setActiveTable] = useState<string>("");
163	  const [tab, setTab] = useState<MainTab>("overview");
164	
165	  const loadTables = useCallback(async () => {
166	    setTablesBusy(true); setTablesErr("");
167	    const res = await dbmgrTableCounts(accountId, activeDb);
168	    setTablesBusy(false);
169	    if (res.error) { setTablesErr(res.error); setTables([]); return; }
170	    setTables(res.tables ?? []);
171	  }, [accountId, activeDb]);
172	
173	  useEffect(() => { loadTables(); }, [loadTables]);
174	
175	  const filtered = useMemo(() => {
176	    const q = filter.trim().toLowerCase();
177	    return q ? tables.filter((t) => t.name.toLowerCase().includes(q)) : tables;
178	  }, [tables, filter]);
179	
180	  function openTable(name: string) {
181	    setActiveTable(name);
182	    setTab((t) => (t === "sql" || t === "import" || t === "overview" ? "browse" : t));
183	  }
184	
185	  // A table was renamed/dropped elsewhere — refresh the tree + reconcile selection.
186	  const onTablesChanged = useCallback((opts?: { removed?: string; renamedTo?: string }) => {
187	    if (opts?.removed && opts.removed === activeTable) { setActiveTable(""); setTab("overview"); }
188	    if (opts?.renamedTo) setActiveTable(opts.renamedTo);
189	    loadTables();
190	  }, [activeTable, loadTables]);
191	
192	  return (
193	    <div className="grid gap-4 lg:grid-cols-[15rem_minmax(0,1fr)]">
194	      {/* Sidebar */}
195	      <aside className="flex flex-col gap-3">
196	        {/* Database picker */}
197	        <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-3">
198	          <p className="section-label mb-2 flex items-center gap-1.5"><DatabaseIcon className="h-3.5 w-3.5" /> Database</p>
199	          {activeDbs.length > 1 ? (
200	            <select className="input py-2 text-xs" value={activeDb} onChange={(e) => onPickDb(e.target.value)}>
201	              {databases.map((d) => (
202	                <option key={d.name} value={d.name} disabled={d.status !== "ACTIVE"}>
203	                  {d.name}{d.status !== "ACTIVE" ? ` (${d.status.toLowerCase()})` : ""}
204	                </option>
205	              ))}
206	            </select>
207	          ) : (
208	            <button
209	              type="button"
210	              onClick={() => { setActiveTable(""); setTab("overview"); }}
211	              className="w-full truncate rounded-lg border border-white/[0.06] bg-navy-900/60 px-2.5 py-2 text-left font-mono text-xs text-slate-200 hover:border-brand-500/30"
212	              title={`${activeDb} — database overview`}
213	            >
214	              {activeDb}
215	            </button>
216	          )}
217	        </div>
218	
219	        {/* Tables tree */}
220	        <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-3">
221	          <div className="mb-2 flex items-center justify-between">
222	            <p className="section-label flex items-center gap-1.5"><TableIcon className="h-3.5 w-3.5" /> Tables {tables.length > 0 && <span className="text-slate-600">({tables.length})</span>}</p>
223	            <button type="button" className="btn-ghost rounded-md px-1.5 py-1 text-[11px]" onClick={loadTables} title="Refresh tables"><RefreshIcon className="h-3.5 w-3.5" /></button>
224	          </div>
225	          <div className="relative mb-2">
226	            <SearchIcon className="pointer-events-none absolute left-2.5 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-slate-500" />
227	            <input className="input py-1.5 pl-8 text-xs" placeholder="Filter tables…" value={filter} onChange={(e) => setFilter(e.target.value)} />
228	          </div>
229	          {tablesBusy && <div className="space-y-1.5 py-1">{[0, 1, 2, 3].map((i) => <div key={i} className="skeleton h-6" />)}</div>}
230	          {tablesErr && <p className="rounded-lg border border-red-500/20 bg-red-500/[0.06] px-2 py-1.5 text-[11px] text-red-200">{tablesErr}</p>}
231	          {!tablesBusy && !tablesErr && tables.length === 0 && <p className="px-1 py-2 text-[11px] text-slate-500">This database has no tables yet. Create one from the SQL or Import tab.</p>}
232	          {!tablesBusy && !tablesErr && tables.length > 0 && filtered.length === 0 && <p className="px-1 py-2 text-[11px] text-slate-500">No tables match “{filter}”.</p>}
233	          <ul className="max-h-[20rem] space-y-0.5 overflow-y-auto">
234	            {filtered.map((t) => {
235	              const active = activeTable === t.name && tab !== "sql" && tab !== "import" && tab !== "overview";
236	              return (
237	                <li key={t.name}>
238	                  <button
239	                    type="button"
240	                    onClick={() => openTable(t.name)}
241	                    className={`group flex w-full items-center gap-2 rounded-lg px-2 py-1.5 text-left transition-colors ${active ? "bg-gradient-to-r from-accent-blue/20 to-brand-500/20 text-brand-100" : "text-slate-300 hover:bg-white/[0.04]"}`}
242	                    title={t.name}
243	                  >
244	                    <TableIcon className={`h-3.5 w-3.5 shrink-0 ${active ? "text-brand-200" : "text-slate-500 group-hover:text-slate-400"}`} />
245	                    <span className="min-w-0 flex-1 truncate font-mono text-xs">{t.name}</span>
246	                    {t.rows != null && <span className="shrink-0 rounded-full bg-white/[0.06] px-1.5 py-0.5 text-[10px] tabular-nums text-slate-400">{fmtCount(t.rows)}</span>}
247	                  </button>
248	                </li>
249	              );
250	            })}
251	          </ul>
252	        </div>
253	
254	        <div className="grid grid-cols-2 gap-2">
255	          <button
256	            type="button"
257	            onClick={() => setTab("sql")}
258	            className={`flex items-center justify-center gap-1.5 rounded-xl border px-2 py-2.5 text-xs font-semibold transition-colors ${tab === "sql" ? "border-brand-500/40 bg-brand-500/15 text-brand-100" : "border-white/[0.06] bg-white/[0.02] text-slate-300 hover:bg-white/[0.05]"}`}
259	          >
260	            <SqlIcon className="h-4 w-4" /> SQL
261	          </button>
262	          <button
263	            type="button"
264	            onClick={() => setTab("import")}
265	            className={`flex items-center justify-center gap-1.5 rounded-xl border px-2 py-2.5 text-xs font-semibold transition-colors ${tab === "import" ? "border-brand-500/40 bg-brand-500/15 text-brand-100" : "border-white/[0.06] bg-white/[0.02] text-slate-300 hover:bg-white/[0.05]"}`}
266	          >
267	            <UploadIcon className="h-4 w-4" /> Import
268	          </button>
269	        </div>
270	      </aside>
271	
272	      {/* Main pane */}
273	      <section className="min-w-0">
274	        <div className="mb-3 flex flex-wrap items-center gap-1 border-b border-white/[0.06] pb-2">
275	          <TabButton active={tab === "overview"} onClick={() => { setActiveTable(""); setTab("overview"); }} icon={<DatabaseIcon className="h-3.5 w-3.5" />}>Overview</TabButton>
276	          <TabButton active={tab === "browse"} disabled={!activeTable} onClick={() => setTab("browse")} icon={<GridIcon className="h-3.5 w-3.5" />}>Browse</TabButton>
277	          <TabButton active={tab === "structure"} disabled={!activeTable} onClick={() => setTab("structure")} icon={<ColumnsIcon className="h-3.5 w-3.5" />}>Structure</TabButton>
278	          <TabButton active={tab === "sql"} onClick={() => setTab("sql")} icon={<SqlIcon className="h-3.5 w-3.5" />}>SQL</TabButton>
279	          <TabButton active={tab === "import"} onClick={() => setTab("import")} icon={<UploadIcon className="h-3.5 w-3.5" />}>Import</TabButton>
280	          {activeTable && (tab === "browse" || tab === "structure") && (
281	            <span className="ml-auto flex items-center gap-1.5 font-mono text-xs text-slate-400"><TableIcon className="h-3.5 w-3.5 text-brand-300" />{activeTable}</span>
282	          )}
283	        </div>
284	
285	        {tab === "overview" && <OverviewPanel accountId={accountId} dbName={activeDb} onOpenTable={openTable} />}
286	        {tab === "sql" && <SqlEditor accountId={accountId} dbName={activeDb} onChanged={loadTables} />}
287	        {tab === "import" && <ImportPanel accountId={accountId} dbName={activeDb} onChanged={loadTables} />}
288	        {(tab === "browse" || tab === "structure") && !activeTable && (
289	          <div className="rounded-xl border border-dashed border-white/[0.08] bg-white/[0.01] px-4 py-12 text-center">
290	            <TableIcon className="mx-auto mb-3 h-7 w-7 text-slate-600" />
291	            <p className="text-sm text-slate-300">Pick a table to get started</p>
292	            <p className="mx-auto mt-1 max-w-xs text-xs text-slate-500">Choose a table from the sidebar to browse its rows and edit its structure, or open the SQL editor.</p>
293	          </div>
294	        )}
295	        {tab === "browse" && activeTable && (
296	          <TableBrowser key={`${activeDb}/${activeTable}`} accountId={accountId} dbName={activeDb} table={activeTable} onDataChanged={loadTables} />
297	        )}
298	        {tab === "structure" && activeTable && (
299	          <StructureView key={`${activeDb}/${activeTable}/s`} accountId={accountId} dbName={activeDb} table={activeTable} onChanged={onTablesChanged} onEditData={() => setTab("browse")} />
300	        )}
301	      </section>
302	    </div>
303	  );
304	}
305	
306	/* ============================================================= OverviewPanel === */
307	
308	function OverviewPanel({ accountId, dbName, onOpenTable }: { accountId: string; dbName: string; onOpenTable: (t: string) => void }) {
309	  const [tables, setTables] = useState<DbMgrOverviewTable[] | null>(null);
310	  const [err, setErr] = useState("");
311	  const [busy, setBusy] = useState(true);
312	
313	  const load = useCallback(async () => {
314	    setBusy(true); setErr("");
315	    const res = await dbmgrDatabaseOverview(accountId, dbName);
316	    setBusy(false);
317	    if (res.error) { setErr(res.error); setTables(null); return; }
318	    setTables(res.tables ?? []);
319	  }, [accountId, dbName]);
320	  useEffect(() => { load(); }, [load]);
321	
322	  const totals = useMemo(() => {
323	    const t = tables ?? [];
324	    return {
325	      tables: t.length,
326	      rows: t.reduce((a, x) => a + (x.rows ?? 0), 0),
327	      data: t.reduce((a, x) => a + (x.dataBytes ?? 0), 0),
328	      index: t.reduce((a, x) => a + (x.indexBytes ?? 0), 0),
329	    };
330	  }, [tables]);
331	
332	  return (
333	    <div>
334	      <div className="mb-3 flex items-center justify-between">
335	        <div>
336	          <h4 className="flex items-center gap-2 text-sm font-semibold text-slate-100"><DatabaseIcon className="h-4 w-4 text-brand-300" /> <span className="font-mono">{dbName}</span></h4>
337	          <p className="mt-0.5 text-[11px] text-slate-500">Database overview — every table with approximate rows, size, engine and collation.</p>
338	        </div>
339	        <button className="btn-ghost rounded-lg px-2 py-1.5 text-xs" onClick={load} title="Refresh"><RefreshIcon className="h-3.5 w-3.5" /></button>
340	      </div>
341	
342	      {!busy && !err && tables && tables.length > 0 && (
343	        <div className="mb-3 grid grid-cols-2 gap-2 sm:grid-cols-4">
344	          <OverviewStat label="Tables" value={totals.tables.toLocaleString()} />
345	          <OverviewStat label="Rows (approx)" value={totals.rows.toLocaleString()} />
346	          <OverviewStat label="Data" value={fmtBytes(totals.data)} />
347	          <OverviewStat label="Indexes" value={fmtBytes(totals.index)} />
348	        </div>
349	      )}
350	
351	      {err && <ErrorBanner msg={err} onClose={() => setErr("")} />}
352	      {busy ? (
353	        <GridSkeleton />
354	      ) : tables && tables.length === 0 ? (
355	        <div className="rounded-xl border border-dashed border-white/[0.08] bg-white/[0.01] px-4 py-10 text-center">
356	          <TableIcon className="mx-auto mb-2 h-6 w-6 text-slate-600" />
357	          <p className="text-sm text-slate-300">No tables in this database yet</p>
358	          <p className="mx-auto mt-1 max-w-xs text-xs text-slate-500">Create one from the SQL editor or the Import tab.</p>
359	        </div>
360	      ) : tables ? (
361	        <div className="overflow-x-auto rounded-xl border border-white/[0.06]">
362	          <table className="min-w-full text-left text-xs">
363	            <thead className="bg-white/[0.03]">
364	              <tr>
365	                {["Table", "Rows", "Data", "Index", "Engine", "Collation"].map((h, i) => (
366	                  <th key={h} className={`whitespace-nowrap border-b border-white/[0.06] px-3 py-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500 ${i > 0 && i < 4 ? "text-right" : ""}`}>{h}</th>
367	                ))}
368	              </tr>
369	            </thead>
370	            <tbody>
371	              {tables.map((t) => (
372	                <tr key={t.name} className="border-t border-white/[0.04] transition-colors odd:bg-white/[0.01] hover:bg-white/[0.03]">
373	                  <td className="whitespace-nowrap px-3 py-1.5">
374	                    <button type="button" onClick={() => onOpenTable(t.name)} className="inline-flex items-center gap-1.5 font-mono font-medium text-brand-200 hover:text-brand-100 hover:underline">
375	                      <TableIcon className="h-3.5 w-3.5 text-slate-500" />{t.name}
376	                    </button>
377	                  </td>
378	                  <td className="px-3 py-1.5 text-right tabular-nums text-slate-300">{t.rows == null ? "·" : t.rows.toLocaleString()}</td>
379	                  <td className="px-3 py-1.5 text-right tabular-nums text-slate-400">{t.dataBytes == null ? "·" : fmtBytes(t.dataBytes)}</td>
380	                  <td className="px-3 py-1.5 text-right tabular-nums text-slate-400">{t.indexBytes == null ? "·" : fmtBytes(t.indexBytes)}</td>
381	                  <td className="px-3 py-1.5 text-slate-400">{t.engine ?? "·"}</td>
382	                  <td className="whitespace-nowrap px-3 py-1.5 font-mono text-[11px] text-slate-500">{t.collation ?? "·"}</td>
383	                </tr>
384	              ))}
385	            </tbody>
386	          </table>
387	        </div>
388	      ) : null}
389	    </div>
390	  );
391	}
392	
393	function OverviewStat({ label, value }: { label: string; value: string }) {
394	  return (
395	    <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2">
396	      <p className="text-[10px] uppercase tracking-wider text-slate-500">{label}</p>
397	      <p className="mt-0.5 text-sm font-semibold tabular-nums text-slate-100">{value}</p>
398	    </div>
399	  );
400	}
401	
402	/* ============================================================ TableBrowser === */
403	
404	type Sort = { col: string; dir: "ASC" | "DESC" } | null;
405	
406	function TableBrowser({ accountId, dbName, table, onDataChanged }: { accountId: string; dbName: string; table: string; onDataChanged: () => void }) {
407	  const [page, setPage] = useState(0);
408	  const [pageSize, setPageSize] = useState(50);
409	  const [sort, setSort] = useState<Sort>(null);
410	  const [reload, setReload] = useState(0);
411	  const [data, setData] = useState<{ columns: string[]; rows: string[][]; total: number | null; pageSize: number; truncated: boolean } | null>(null);
412	  const [err, setErr] = useState("");
413	  const [busy, setBusy] = useState(false);
414	
415	  // Filtering: a global quick-search + per-column filters (applied on submit).
416	  const [search, setSearch] = useState("");
