251	/** Browse a page of a table's rows. Validates the table by MEMBERSHIP against the
252	 *  db's real table list (so a user can't name a table they can't see), then runs
253	 *  a bounded SELECT + a COUNT. Supports per-column LIKE filters, a global quick
254	 *  search across text columns, sorting, and a chosen page size — all identifiers
255	 *  membership-validated, all values `?`-bound. Owner-or-admin + not-impersonating. */
256	export async function dbmgrBrowseTable(
257	  accountId: string,
258	  dbName: string,
259	  table: string,
260	  opts: DbMgrBrowseOpts = {},
261	): Promise<DbMgrBrowseResult> {
262	  const ctx = await loadOwned(accountId);
263	  if ("error" in ctx) return { error: ctx.error };
264	  await assertNotImpersonating();
265	  const { user } = ctx;
266	  if (!(await assertOwnedDatabase(accountId, dbName))) return { error: "Unknown database." };
267	  if (!isPlausibleTableName(table)) return { error: "Invalid table name." };
268	  if (!rlOk(user.id, accountId)) return { error: "Too many requests — slow down a moment." };
269	  const p = Math.max(0, Math.floor(Number(opts.page) || 0));
270	  const pageSize = clampPageSize(opts.pageSize ?? BROWSE_PAGE_SIZE);
271	  const dir: "ASC" | "DESC" = opts.sortDir === "DESC" ? "DESC" : "ASC";
272	  const search = String(opts.search ?? "").trim();
273	
274	  if (SANDBOX) {
275	    const demo = sandboxResult("select");
276	    return { columns: demo.columns, rows: demo.rows, total: demo.rows.length, page: p, pageSize, truncated: false, sortColumn: opts.sortColumn ?? null, sortDir: dir };
277	  }
278	  const target = dbTargetFor(ctx.a);
279	  if (!target) return { error: "The database manager is still being prepared." };
280	
281	  // Membership check: the table MUST be one the scoped user can actually see.
282	  const listed = await runScopedSql(target, dbName, showTablesSql());
283	  if (listed.error) return { error: listed.error };
284	  const tables = listed.rows.map((r) => r[0]);
285	  if (!tables.includes(table)) return { error: "Unknown table." };
286	
287	  // Load the real columns (name + type) once — the sole source for validating
288	  // every identifier we embed (sort col, filter cols, search cols).
289	  const colsRes = await runScopedSql(target, dbName, showFullColumnsSql(table));
290	  if (colsRes.error) return { error: colsRes.error };
291	  const realCols = colsRes.rows.map((r) => r[0]);
292	  const realSet = new Set(realCols);
293	  const textCols = colsRes.rows.filter((r) => TEXTY_TYPE_RE.test(r[1] ?? "")).map((r) => r[0]);
294	
295	  // Sort column validated by MEMBERSHIP before it can be backtick-quoted.
296	  let order: { col: string; dir: "ASC" | "DESC" } | undefined;
297	  if (opts.sortColumn && realSet.has(opts.sortColumn)) order = { col: opts.sortColumn, dir };
298	
299	  // Per-column filters: keep only real columns; bind each value as `%v%`.
300	  const filterCols: string[] = [];
301	  const filterValues: string[] = [];
302	  for (const f of opts.filters ?? []) {
303	    if (f && realSet.has(f.column) && String(f.value ?? "") !== "") {
304	      filterCols.push(f.column);
305	      filterValues.push(`%${likeEscape(String(f.value))}%`);
306	    }
307	  }
308	  // Global search: OR LIKE across text columns (all columns if none are texty),
309	  // one bound `%term%` per column.
310	  const searchCols = search ? (textCols.length ? textCols : realCols) : [];
311	  const searchValues = searchCols.map(() => `%${likeEscape(search)}%`);
312	
313	  const hasFilter = filterCols.length > 0 || searchCols.length > 0;
314	  const sql = hasFilter
315	    ? filteredBrowseSql(table, filterCols, searchCols, pageSize, p * pageSize, order)
316	    : browseTableSql(table, pageSize, p * pageSize, order);
317	  const params = [...filterValues, ...searchValues];
318	  const res = await runScopedSql(target, dbName, sql, hasFilter ? params : undefined);
319	  if (res.error) return { error: res.error };
320	
321	  const countSql = hasFilter ? countFilteredSql(table, filterCols, searchCols) : countTableSql(table);
322	  const countRes = await runScopedSql(target, dbName, countSql, hasFilter ? params : undefined);
323	  const total = countRes.error ? null : Number(countRes.rows[0]?.[0] ?? "0");
324	  return { columns: res.columns, rows: res.rows, total: Number.isFinite(total as number) ? (total as number) : null, page: p, pageSize, truncated: res.truncated, sortColumn: order?.col ?? null, sortDir: dir };
325	}
