336	 * the mysql2 protocol driver over an SSH-forwarded channel to the node's localhost
337	 * MySQL (never a `mysql` CLI, never a shell), executed as the scoped manager user —
338	 * MySQL's grant is the hard isolation boundary, and there is no CLI meta-command
339	 * interpreter to abuse. Owner-or-admin + not-impersonating + rate-limited.
340	 */
341	export async function dbmgrRunSql(accountId: string, dbName: string, sql: string): Promise<DbMgrResult> {
342	  const empty: DbMgrResult = { columns: [], rows: [], truncated: false, error: null, elapsedMs: 0 };
343	  const ctx = await loadOwned(accountId);
344	  if ("error" in ctx) return { ...empty, error: ctx.error ?? null };
345	  await assertNotImpersonating();
346	  const { user } = ctx;
347	  if (!(await assertOwnedDatabase(accountId, dbName))) return { ...empty, error: "Unknown database." };
348	  const text = String(sql ?? "").trim();
349	  if (!text) return { ...empty, error: "Enter a SQL statement." };
350	  if (Buffer.byteLength(text, "utf8") > MAX_SQL_BYTES) return { ...empty, error: "That query is too large." };
351	  if (!rlOk(user.id, accountId)) return { ...empty, error: "Too many requests — slow down a moment." };
