353	  if (SANDBOX) return sandboxResult(text);
354	  const target = dbTargetFor(ctx.a);
355	  if (!target) return { ...empty, error: "The database manager is still being prepared." };
356	  const res: QueryResult = await runScopedSql(target, dbName, text);
357	  if (res.error) return { ...res, error: res.error };
358	  return { ...res, ok: res.columns.length === 0 };
