408	/** Fetch a table's structure (columns, indexes, primary key) as the scoped user.
409	 *  Assumes membership has already been asserted for `table`. */
410	async function fetchStructure(target: DbNodeTarget, dbName: string, table: string): Promise<{ error: string } | { structure: DbMgrStructure }> {
411	  const cols = await runScopedSql(target, dbName, showFullColumnsSql(table));
412	  if (cols.error) return { error: cols.error };
413	  // SHOW FULL COLUMNS positional order: Field, Type, Collation, Null, Key, Default, Extra, Privileges, Comment.
414	  const columns: DbMgrColumn[] = cols.rows.map((r) => ({
415	    name: r[0],
416	    type: r[1],
417	    nullable: (r[3] ?? "").toUpperCase() === "YES",
418	    key: r[4] ?? "",
419	    default: r[5] === NULL_SENTINEL ? null : (r[5] ?? null),
420	    extra: r[6] ?? "",
421	    comment: r[8] ?? "",
422	  }));
423	
424	  const idx = await runScopedSql(target, dbName, showIndexSql(table));
425	  // SHOW INDEX positional: Table, Non_unique, Key_name, Seq_in_index, Column_name, ...
426	  const byName = new Map<string, { name: string; unique: boolean; cols: Array<{ seq: number; col: string }> }>();
427	  if (!idx.error) {
428	    for (const r of idx.rows) {
429	      const keyName = r[2];
430	      const nonUnique = r[1] === "1";
431	      const seq = Number(r[3] ?? "0") || 0;
432	      const col = r[4];
433	      const entry = byName.get(keyName) ?? { name: keyName, unique: !nonUnique, cols: [] };
434	      entry.cols.push({ seq, col });
435	      byName.set(keyName, entry);
436	    }
437	  }
438	  const indexes: DbMgrIndex[] = [...byName.values()].map((e) => ({
439	    name: e.name,
440	    unique: e.unique,
441	    columns: e.cols.sort((a, b) => a.seq - b.seq).map((c) => c.col),
442	  }));
443	  const primaryKey = indexes.find((i) => i.name === "PRIMARY")?.columns
444	    ?? columns.filter((c) => c.key === "PRI").map((c) => c.name);
445	
446	  return { structure: { columns, indexes, primaryKey } };
447	}
