510	/** Resolve the WHERE columns that identify an existing row: prefer the PRIMARY
511	 *  KEY (when every PK column is present in `where`), else fall back to every
512	 *  supplied real column. Returns [] when the row can't be safely identified. */
513	function whereColumnsFor(where: Record<string, DbCellValue>, structure: DbMgrStructure, real: Set<string>): string[] {
514	  const supplied = keepValidColumns(Object.keys(where ?? {}), real);
515	  const pk = structure.primaryKey;
516	  if (pk.length > 0 && pk.every((c) => c in (where ?? {}))) return pk;
517	  return supplied;
