570	/** Build a downloadable SQL dump of a single table (CREATE TABLE + a bounded set
571	 *  of INSERTs) via the scoped connection — no root, no mysqldump. Values are
572	 *  escaped by the mysql2 string-escaper. Bounded by the transport's row cap.
573	 *  Owner-or-admin + not-impersonating. */
574	export async function dbmgrExportTable(accountId: string, dbName: string, table: string, format: "sql" | "csv" = "sql"): Promise<{ error?: string; filename?: string; content?: string; mime?: string; truncated?: boolean }> {
575	  const lt = await liveTarget(accountId, dbName);
576	  if ("error" in lt) return { error: lt.error };
577	  if (lt.mode === "sandbox") {
578	    return format === "csv"
579	      ? { filename: `${table}.csv`, content: "id,name\r\n", mime: "text/csv", truncated: false }
580	      : { filename: `${table}.sql`, content: `-- Nxeon DB Studio (sandbox) export of \`${table}\`\n`, mime: "application/sql", truncated: false };
581	  }
582	  const vis = await tableIsVisible(lt.target, dbName, table);
583	  if ("error" in vis) return { error: vis.error };
584	
585	  // CSV: just the data (header + rows), bounded by the transport row cap.
586	  if (format === "csv") {
587	    const data = await runScopedSql(lt.target, dbName, dumpSelectSql(table));
588	    if (data.error) return { error: data.error };
589	    return { filename: `${table}.csv`, content: toCsv(data.columns, data.rows), mime: "text/csv", truncated: data.truncated };
590	  }
591	
592	  const create = await runScopedSql(lt.target, dbName, showCreateTableSql(table));
593	  if (create.error) return { error: create.error };
594	  // SHOW CREATE TABLE returns one row: [Table, "Create Table"].
595	  const createStmt = create.rows[0]?.[1] ?? "";
596	
597	  const s = await fetchStructure(lt.target, dbName, table);
598	  if ("error" in s) return { error: s.error };
599	  const colNames = s.structure.columns.map((c) => c.name);
600	
601	  const data = await runScopedSql(lt.target, dbName, dumpSelectSql(table));
602	  if (data.error) return { error: data.error };
603	
604	  const lines: string[] = [];
605	  lines.push(`-- Nxeon DB Studio export`);
606	  lines.push(`-- database: ${dbName}`);
607	  lines.push(`-- table:    ${table}`);
608	  lines.push(`-- generated: ${new Date().toISOString()}`);
609	  lines.push(`-- rows:     ${data.rows.length}${data.truncated ? ` (truncated at ${data.rows.length})` : ""}`);
610	  lines.push("");
611	  lines.push("SET FOREIGN_KEY_CHECKS=0;");
612	  lines.push(`DROP TABLE IF EXISTS ${quoteIdent(table)};`);
613	  lines.push(`${createStmt};`);
614	  lines.push("");
615	  if (data.rows.length > 0) {
616	    const colList = colNames.map((c) => quoteIdent(c)).join(", ");
617	    for (const row of data.rows) {
618	      const vals = row.map((cell) => dumpValueLiteral(cell)).join(", ");
619	      lines.push(`INSERT INTO ${quoteIdent(table)} (${colList}) VALUES (${vals});`);
620	    }
621	  }
622	  lines.push("");
623	  lines.push("SET FOREIGN_KEY_CHECKS=1;");
624	  return { filename: `${table}.sql`, content: lines.join("\n"), mime: "application/sql", truncated: data.truncated };
625	}
