781	/** Run a pasted / uploaded SQL script statement-by-statement. The script is split
782	 *  locally (quote/comment-aware) and each statement is shipped on its own through
783	 *  the scoped, capped `runScopedSql` transport (multipleStatements stays OFF — we
784	 *  never send a stacked query). Stops at the first error and reports per-statement
785	 *  results. Owner-or-admin + not-impersonating + rate-limited. */
786	export async function dbmgrImportSql(accountId: string, dbName: string, script: string): Promise<DbMgrImportResult> {
