789	  const text = String(script ?? "");
790	  if (!text.trim()) return { error: "Paste or upload a SQL script to import." };
791	  if (Buffer.byteLength(text, "utf8") > MAX_SQL_BYTES * 8) return { error: "That script is too large to import here — split it into smaller files." };
792	  const statements = splitSqlStatements(text);
793	  if (statements.length === 0) return { error: "No runnable statements found." };
794	  if (statements.length > MAX_IMPORT_STATEMENTS) return { error: `Too many statements (${statements.length}); the import cap is ${MAX_IMPORT_STATEMENTS}. Split the file.` };
795	
796	  if (lt.mode === "sandbox") {
797	    return { results: statements.map((s) => ({ sql: s, ok: true, error: null, rows: 0, elapsedMs: 1 })), ranAll: true };
798	  }
799	
800	  const results: DbMgrImportStatement[] = [];
801	  for (const stmt of statements) {
802	    const res = await runScopedSql(lt.target, dbName, stmt);
803	    results.push({ sql: stmt, ok: !res.error, error: res.error, rows: res.rows.length, elapsedMs: res.elapsedMs });
804	    if (res.error) return { results, ranAll: false }; // stop at the first failure
805	  }
806	  return { results, ranAll: true };
807	}
