1211	type FieldState = { value: string; isNull: boolean; include: boolean };
1212	
1213	function RowEditor({
1214	  mode,
1215	  heading,
1216	  table,
1217	  structure,
1218	  original,
1219	  initial,
1220	  onClose,
1221	  onSave,
1222	}: {
1223	  mode: "insert" | "edit";
1224	  heading: string;
1225	  table: string;
1226	  structure: DbMgrStructure;
1227	  original: Record<string, DbCellValue> | null;
1228	  initial?: Record<string, DbCellValue> | null;
1229	  onClose: () => void;
1230	  onSave: (payload: { values: Record<string, DbCellValue>; changes: Record<string, DbCellValue> }) => Promise<string | null>;
1231	}) {
1232	  const [fields, setFields] = useState<Record<string, FieldState>>(() => {
1233	    const init: Record<string, FieldState> = {};
1234	    for (const c of structure.columns) {
1235	      if (mode === "edit" && original) {
1236	        const v = original[c.name];
1237	        init[c.name] = { value: v === null ? "" : (v ?? ""), isNull: v === null, include: true };
1238	      } else if (initial && c.name in initial) {
1239	        const v = initial[c.name];
1240	        init[c.name] = { value: v === null ? "" : (v ?? ""), isNull: v === null, include: true };
1241	      } else {
1242	        // Insert: pre-omit auto_increment / defaulted columns so the DB fills them.
1243	        const auto = /auto_increment/i.test(c.extra) || c.default !== null;
1244	        init[c.name] = { value: "", isNull: false, include: !auto };
1245	      }
1246	    }
1247	    return init;
1248	  });
1249	  const [err, setErr] = useState("");
1250	  const [busy, setBusy] = useState(false);
1251	
1252	  function set(name: string, patch: Partial<FieldState>) {
1253	    setFields((f) => ({ ...f, [name]: { ...f[name], ...patch } }));
1254	  }
1255	
1256	  async function submit() {
1257	    setBusy(true); setErr("");
1258	    const values: Record<string, DbCellValue> = {};
1259	    const changes: Record<string, DbCellValue> = {};
1260	    for (const c of structure.columns) {
1261	      const f = fields[c.name];
1262	      const val: DbCellValue = f.isNull ? null : f.value;
1263	      if (mode === "insert") {
1264	        if (f.include) values[c.name] = val;
1265	      } else {
1266	        const orig = original ? original[c.name] ?? null : null;
1267	        const origNorm = orig === null ? null : String(orig);
1268	        const nextNorm = f.isNull ? null : f.value;
1269	        if (origNorm !== nextNorm) changes[c.name] = val;
1270	      }
