1331	  const [pendingConfirm, setPendingConfirm] = useState(false);
1332	  const [history, setHistory] = useState<HistItem[]>([]);
1333	  const [showHistory, setShowHistory] = useState(false);
1334	
1335	  const histKey = `nxeon-dbstudio-sqlhistory:${accountId}:${dbName}`;
1336	  useEffect(() => {
1337	    try { const raw = localStorage.getItem(histKey); if (raw) setHistory(JSON.parse(raw)); } catch { /* */ }
1338	  }, [histKey]);
1339	
1340	  function pushHistory(q: string) {
1341	    const trimmed = q.trim();
1342	    if (!trimmed) return;
1343	    setHistory((h) => {
1344	      const next = [{ sql: trimmed, at: Date.now() }, ...h.filter((x) => x.sql !== trimmed)].slice(0, 25);
1345	      try { localStorage.setItem(histKey, JSON.stringify(next)); } catch { /* */ }
1346	      return next;
1347	    });
1348	  }
1349	  function clearHistory() {
1350	    setHistory([]);
1351	    try { localStorage.removeItem(histKey); } catch { /* */ }
1352	  }
1353	
1354	  async function execute() {
1355	    setBusy(true); setErr(""); setNote(""); setResult(null); setPendingConfirm(false);
