1368	  }
1369	
1370	  function run() {
1371	    if (!sql.trim()) return;
1372	    if (DESTRUCTIVE_RE.test(sql)) { setPendingConfirm(true); return; }
1373	    execute();
1374	  }
1375	
1376	  return (
1377	    <div>
