1384	          <HistoryIcon className="h-3.5 w-3.5" /> History{history.length ? ` (${history.length})` : ""}
1385	        </button>
1386	      </div>
1387	
1388	      <div className="grid gap-3 lg:grid-cols-[minmax(0,1fr)_auto]">
1389	        <div>
1390	          <div className="overflow-hidden rounded-xl border border-white/[0.08] focus-within:border-brand-400/50 focus-within:ring-2 focus-within:ring-brand-500/20">
1391	            <textarea
1392	              className="block h-52 w-full resize-y bg-navy-900/80 px-3.5 py-3 font-mono text-xs leading-relaxed text-slate-100 outline-none placeholder:text-slate-600"
1393	              placeholder="SELECT * FROM your_table LIMIT 20;"
1394	              spellCheck={false}
1395	              value={sql}
1396	              onChange={(e) => setSql(e.target.value)}
