1404	            {note && <span className="ml-auto text-[11px] text-slate-400">{note}</span>}
1405	          </div>
1406	        </div>
1407	
1408	        {showHistory && history.length > 0 && (
1409	          <aside className="w-full lg:w-64">
1410	            <div className="mb-1.5 flex items-center justify-between">
1411	              <p className="section-label">Query history</p>
1412	              <button className="text-[11px] text-slate-500 hover:text-red-300" onClick={clearHistory}>Clear</button>
1413	            </div>
1414	            <ul className="max-h-52 space-y-1 overflow-y-auto rounded-xl border border-white/[0.06] bg-white/[0.02] p-2">
1415	              {history.map((h, i) => (
