281	/** Row cap. We hard-limit rows so a caller that forgets a LIMIT still can't pull
282	 *  an unbounded set into memory/over the wire. */
283	export const MAX_ROWS = 1000;
284	
285	/** Sentinel a NULL cell resolves to (chosen so it can't collide with a real
286	 *  value; the UI renders it as a muted "NULL"). */
287	export const NULL_CELL = " NULL ";
