289	// ---- Safe SQL builders for the browse UI ------------------------------------
290	// The table name here is USER-CHOSEN. MySQL cannot bind an identifier as a
291	// prepared-statement parameter, so it only ever lands inside a backtick-quoted
292	// identifier in SQL that travels over the mysql2 wire (never a shell, never a
293	// CLI argv). We (1) accept only a conservative identifier charset, (2) double any
294	// backtick, and (3) the caller additionally checks membership against SHOW TABLES,
295	// so a value can neither break out of the quotes nor name a table the user can't
296	// see. LIMIT/OFFSET are integer-clamped and embedded as plain numbers.
297	
298	const TABLE_IDENT_RE = /^[A-Za-z0-9_$ .-]{1,64}$/;
299	export function isPlausibleTableName(name: string): boolean {
300	  return TABLE_IDENT_RE.test(String(name ?? ""));
301	}
302	
303	/** Quote an identifier for embedding between backticks (double internal ``` ` ```). */
304	export function quoteIdent(name: string): string {
305	  return "`" + String(name).replace(/`/g, "``") + "`";
306	}
307	
308	/** Default page size for the row browser (rows per page). */
309	export const BROWSE_PAGE_SIZE = 50;
310	/** Hard ceiling on a single browse page. The transport's MAX_ROWS (1000) is the
311	 *  ultimate cap; this bounds one UI page so "rows per page" stays sane. */
312	export const MAX_BROWSE_PAGE_SIZE = 200;
313	/** The rows-per-page choices the UI offers. */
314	export const PAGE_SIZE_OPTIONS = [25, 50, 100, 200] as const;
315	
316	export function showTablesSql(): string {
317	  return "SHOW TABLES;";
318	}
319	
320	/** All base tables in a database + their (approximate, storage-engine-reported)
321	 *  row counts, in ONE round-trip. The schema name is bound as a `?` param (never
322	 *  interpolated). `information_schema` rows are already filtered by MySQL to
323	 *  objects the connecting scoped user can see, so this can only reveal the
324	 *  account's own tables. Used to paint the sidebar tree with counts cheaply. */
325	export function tableCountsSql(): string {
326	  return "SELECT TABLE_NAME, TABLE_ROWS FROM information_schema.TABLES WHERE TABLE_SCHEMA = ? AND TABLE_TYPE = 'BASE TABLE' ORDER BY TABLE_NAME;";
327	}
328	
329	/** A bounded page of a table's rows. `offset`/`limit` are clamped to integers by
330	 *  the caller; embedded here as plain numbers (never strings). An optional ORDER
331	 *  BY column is backtick-quoted — the CALLER must have validated it by membership
332	 *  against the table's real columns first; `dir` is coerced to a literal keyword. */
333	export function browseTableSql(table: string, limit: number, offset: number, order?: { col: string; dir: "ASC" | "DESC" }): string {
334	  const lim = clampPageSize(limit);
335	  const off = Math.max(0, Math.floor(offset));
336	  const orderClause = order ? ` ORDER BY ${quoteIdent(order.col)} ${order.dir === "DESC" ? "DESC" : "ASC"}` : "";
337	  return `SELECT * FROM ${quoteIdent(table)}${orderClause} LIMIT ${lim} OFFSET ${off};`;
338	}
339	
340	/** Clamp a requested page size to [1, MAX_BROWSE_PAGE_SIZE] (integer). */
341	export function clampPageSize(n: number): number {
342	  return Math.max(1, Math.min(MAX_BROWSE_PAGE_SIZE, Math.floor(Number(n) || BROWSE_PAGE_SIZE)));
343	}
344	
345	/** Build the WHERE fragment (sans the `WHERE` keyword) for the browse grid's
346	 *  filtering: per-column LIKE filters (ANDed) plus an optional global search
347	 *  term ORed across the given text columns. Every column name MUST have been
348	 *  validated by MEMBERSHIP against the table's real columns before it reaches
349	 *  here; values are NEVER embedded — they are returned as `?` placeholders and
350	 *  bound by the caller in exactly this order:
351	 *    [...one value per filterCol, ...one search term per searchCol].
352	 *  Returns { clause } where clause is "" when there is nothing to filter. */
353	export function browseWhereClause(filterCols: string[], searchCols: string[]): { clause: string } {
354	  const parts: string[] = [];
355	  for (const c of filterCols) parts.push(`${quoteIdent(c)} LIKE ?`);
356	  if (searchCols.length > 0) {
357	    parts.push(`(${searchCols.map((c) => `${quoteIdent(c)} LIKE ?`).join(" OR ")})`);
358	  }
359	  return { clause: parts.length ? ` WHERE ${parts.join(" AND ")}` : "" };
360	}
361	
362	/** A filtered page of rows. Same guarantees as browseTableSql; the WHERE comes
363	 *  from browseWhereClause (validated identifiers, `?`-bound values). */
364	export function filteredBrowseSql(
365	  table: string,
366	  filterCols: string[],
367	  searchCols: string[],
368	  limit: number,
369	  offset: number,
370	  order?: { col: string; dir: "ASC" | "DESC" },
371	): string {
372	  const lim = clampPageSize(limit);
373	  const off = Math.max(0, Math.floor(offset));
374	  const { clause } = browseWhereClause(filterCols, searchCols);
375	  const orderClause = order ? ` ORDER BY ${quoteIdent(order.col)} ${order.dir === "DESC" ? "DESC" : "ASC"}` : "";
376	  return `SELECT * FROM ${quoteIdent(table)}${clause}${orderClause} LIMIT ${lim} OFFSET ${off};`;
377	}
378	
379	export function countTableSql(table: string): string {
380	  return `SELECT COUNT(*) AS n FROM ${quoteIdent(table)};`;
381	}
382	
383	/** COUNT(*) with the same filter WHERE as filteredBrowseSql (for the total). */
384	export function countFilteredSql(table: string, filterCols: string[], searchCols: string[]): string {
385	  const { clause } = browseWhereClause(filterCols, searchCols);
386	  return `SELECT COUNT(*) AS n FROM ${quoteIdent(table)}${clause};`;
387	}
388	
389	// ---- Structure + parameterized DML builders (for the row editor) ------------
390	// Every builder below quotes identifiers with `quoteIdent` (backtick-doubled) and
391	// leaves user VALUES as `?` placeholders, bound by mysql2 (escaped, never string-
392	// concatenated). Callers MUST validate the table by membership (SHOW TABLES) and
393	// each column name by membership (SHOW COLUMNS) before passing it in, so a name
394	// can only ever be one the scoped `_mgr` user is already allowed to see.
395	
396	export function showFullColumnsSql(table: string): string {
397	  return `SHOW FULL COLUMNS FROM ${quoteIdent(table)};`;
398	}
399	
400	export function showIndexSql(table: string): string {
401	  return `SHOW INDEX FROM ${quoteIdent(table)};`;
402	}
403	
404	export function showCreateTableSql(table: string): string {
405	  return `SHOW CREATE TABLE ${quoteIdent(table)};`;
406	}
407	
408	/** Bounded full-table SELECT for an export dump — capped at MAX_ROWS (the same
409	 *  row cap the transport enforces anyway), so an export can never pull an
410	 *  unbounded set. Rows beyond the cap are reported as truncated by the transport. */
411	export function dumpSelectSql(table: string): string {
412	  return `SELECT * FROM ${quoteIdent(table)} LIMIT ${MAX_ROWS};`;
413	}
414	
415	/** `INSERT INTO t (c1,c2) VALUES (?,?)` — the caller passes one param per column,
416	 *  in the same order as `cols`. `cols` must be validated column names. */
417	export function insertRowSql(table: string, cols: string[]): string {
418	  const idents = cols.map(quoteIdent).join(", ");
419	  const marks = cols.map(() => "?").join(", ");
420	  return `INSERT INTO ${quoteIdent(table)} (${idents}) VALUES (${marks});`;
421	}
422	
423	/** `UPDATE t SET c1=?,... WHERE w1<=>? AND ... LIMIT 1`. Params order is:
424	 *  [...set values, ...where values]. `<=>` is MySQL's NULL-safe equality so a row
425	 *  whose key column is NULL still matches. LIMIT 1 bounds a non-unique match. */
426	export function updateRowSql(table: string, setCols: string[], whereCols: string[]): string {
427	  const setClause = setCols.map((c) => `${quoteIdent(c)} = ?`).join(", ");
428	  const whereClause = whereCols.map((c) => `${quoteIdent(c)} <=> ?`).join(" AND ");
429	  return `UPDATE ${quoteIdent(table)} SET ${setClause} WHERE ${whereClause} LIMIT 1;`;
430	}
431	
432	/** `DELETE FROM t WHERE w1<=>? AND ... LIMIT 1`. Params: the where values. */
433	export function deleteRowSql(table: string, whereCols: string[]): string {
434	  const whereClause = whereCols.map((c) => `${quoteIdent(c)} <=> ?`).join(" AND ");
435	  return `DELETE FROM ${quoteIdent(table)} WHERE ${whereClause} LIMIT 1;`;
436	}
437	
438	/** Render one browse-grid cell as a SQL literal for an export dump. The NULL
439	 *  sentinel becomes the `NULL` keyword; every other value is escaped by the
440	 *  mysql2 string-escaper (single-quoted, backslash/quote-safe) — MySQL accepts a
441	 *  quoted string for numeric/date columns on import, so a per-type cast isn't
442	 *  needed for a faithful re-import. */
443	export function dumpValueLiteral(cell: string): string {
444	  if (cell === NULL_CELL) return "NULL";
445	  return sqlEscape(cell);
446	}
447	
448	/** Render one browse-grid cell for a CSV export. NULL becomes an empty field;
449	 *  everything else is RFC-4180 quoted (double any internal quote, wrap in quotes
450	 *  when it contains a comma / quote / newline). Pure string transform — no SQL. */
451	export function csvCell(cell: string): string {
452	  if (cell === NULL_CELL) return "";
453	  const s = String(cell);
454	  return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
455	}
456	
457	/** Build a CSV document from a browse result (header row + data rows). */
458	export function toCsv(columns: string[], rows: string[][]): string {
459	  const head = columns.map((c) => csvCell(c)).join(",");
460	  const body = rows.map((r) => r.map((v) => csvCell(v)).join(",")).join("\r\n");
461	  return rows.length ? `${head}\r\n${body}\r\n` : `${head}\r\n`;
462	}
463	
464	// ---- Database-overview builder ----------------------------------------------
465	// One round-trip that paints the "no table selected" overview: every base table
466	// with its approximate row count, data/index size, engine and collation. The
467	// schema is bound as a `?` param (never interpolated); information_schema rows
468	// are already filtered by MySQL to objects the scoped user can see.
469	
470	export function overviewSql(): string {
471	  return (
472	    "SELECT TABLE_NAME, TABLE_ROWS, DATA_LENGTH, INDEX_LENGTH, ENGINE, TABLE_COLLATION " +
473	    "FROM information_schema.TABLES " +
474	    "WHERE TABLE_SCHEMA = ? AND TABLE_TYPE = 'BASE TABLE' " +
475	    "ORDER BY TABLE_NAME;"
476	  );
477	}
478	
479	// ---- Structure / DDL builders -----------------------------------------------
480	// DDL cannot use `?` placeholders for identifiers OR for the column type, so
481	// everything embedded here MUST be pre-validated by the caller:
482	//   * table / column / index names → membership check (SHOW TABLES / SHOW COLUMNS)
483	//     or isSimpleIdent for a NEW name, then quoteIdent (backtick-doubled).
484	//   * a NEW column's type → isValidColumnType (strict allow-list of base types +
485	//     an optional (n) / (n,m) length), then embedded verbatim.
486	// There are NO user VALUES in any DDL statement below (no DEFAULT expressions),
487	// so there is no value-injection surface; only pre-validated identifiers/types.
488	
489	/** A strict identifier for a brand-new object name (column, index, renamed
490	 *  table): letters/digits/underscore only, 1-64 chars. Tighter than
491	 *  isPlausibleTableName (which tolerates existing names with spaces/dots). */
492	export function isSimpleIdent(name: string): boolean {
493	  return /^[A-Za-z0-9_]{1,64}$/.test(String(name ?? ""));
494	}
495	
496	/** Allow-list of column base types the "add column" form accepts, with an
497	 *  optional length/precision. Anything else is rejected before it can be
498	 *  embedded in DDL. Case-insensitive; returns the normalised (upper-cased base,
499	 *  original digits) type, or null when invalid. */
500	export function normalizeColumnType(raw: string): string | null {
501	  const s = String(raw ?? "").trim();
502	  const m = /^([A-Za-z]+)\s*(\(\s*\d{1,4}\s*(,\s*\d{1,4}\s*)?\))?$/.exec(s);
503	  if (!m) return null;
504	  const base = m[1].toUpperCase();
505	  const ALLOWED = new Set([
506	    "TINYINT", "SMALLINT", "MEDIUMINT", "INT", "INTEGER", "BIGINT",
507	    "DECIMAL", "NUMERIC", "FLOAT", "DOUBLE", "BIT",
508	    "DATE", "DATETIME", "TIMESTAMP", "TIME", "YEAR",
509	    "CHAR", "VARCHAR", "BINARY", "VARBINARY",
510	    "TINYTEXT", "TEXT", "MEDIUMTEXT", "LONGTEXT",
511	    "TINYBLOB", "BLOB", "MEDIUMBLOB", "LONGBLOB",
512	    "JSON", "BOOLEAN", "BOOL",
513	  ]);
514	  if (!ALLOWED.has(base)) return null;
515	  const len = m[2] ? m[2].replace(/\s+/g, "") : "";
516	  return `${base}${len}`;
517	}
518	
519	export function truncateTableSql(table: string): string {
520	  return `TRUNCATE TABLE ${quoteIdent(table)};`;
521	}
522	export function dropTableSql(table: string): string {
523	  return `DROP TABLE ${quoteIdent(table)};`;
524	}
525	export function renameTableSql(table: string, to: string): string {
526	  return `RENAME TABLE ${quoteIdent(table)} TO ${quoteIdent(to)};`;
527	}
528	/** OPTIMIZE / ANALYZE — `op` is a caller-chosen literal keyword, never user text. */
529	export function maintainTableSql(op: "OPTIMIZE" | "ANALYZE", table: string): string {
530	  const kw = op === "ANALYZE" ? "ANALYZE" : "OPTIMIZE";
531	  return `${kw} TABLE ${quoteIdent(table)};`;
532	}
533	/** ADD COLUMN. `typeDef` MUST already be normalizeColumnType output. */
534	export function addColumnSql(table: string, name: string, typeDef: string, nullable: boolean): string {
535	  return `ALTER TABLE ${quoteIdent(table)} ADD COLUMN ${quoteIdent(name)} ${typeDef} ${nullable ? "NULL" : "NOT NULL"};`;
536	}
537	export function dropColumnSql(table: string, name: string): string {
538	  return `ALTER TABLE ${quoteIdent(table)} DROP COLUMN ${quoteIdent(name)};`;
539	}
540	/** ADD [UNIQUE] INDEX over one-or-more validated columns. `indexName` is a
541	 *  validated simple identifier. */
542	export function addIndexSql(table: string, indexName: string, cols: string[], unique: boolean): string {
543	  const colList = cols.map(quoteIdent).join(", ");
544	  return `ALTER TABLE ${quoteIdent(table)} ADD ${unique ? "UNIQUE " : ""}INDEX ${quoteIdent(indexName)} (${colList});`;
545	}
546	export function dropIndexSql(table: string, indexName: string): string {
547	  return `ALTER TABLE ${quoteIdent(table)} DROP INDEX ${quoteIdent(indexName)};`;
548	}
549	
550	// ---- SQL statement splitter (for Import) ------------------------------------
551	// Split a pasted / uploaded script into individual statements so each one can be
552	// run on its own through runScopedSql (multipleStatements stays OFF — we never
553	// ship a stacked query). Quote-, backtick- and comment-aware so a `;` inside a
554	// string/identifier/comment doesn't split a statement. This is a plain string
555	// scan; it grants no new capability — every produced statement still passes
556	// through the same scoped, capped transport as a hand-typed query.
557	
558	/** Max statements we will run from one Import (bounds a giant paste). */
559	export const MAX_IMPORT_STATEMENTS = 200;
560	
561	export function splitSqlStatements(script: string): string[] {
562	  const src = String(script ?? "");
563	  const out: string[] = [];
564	  let buf = "";
565	  let i = 0;
566	  const n = src.length;
567	  type Q = "'" | '"' | "`" | null;
568	  let quote: Q = null;
569	  while (i < n) {
570	    const ch = src[i];
571	    const next = src[i + 1];
572	    if (quote) {
573	      buf += ch;
574	      if (ch === "\\" && quote !== "`") {
575	        // Backslash escape inside '...'/"..." — consume the escaped char.
576	        if (i + 1 < n) { buf += src[i + 1]; i += 2; continue; }
577	      }
578	      if (ch === quote) {
579	        // A doubled quote is an escaped quote, not a close.
580	        if (next === quote) { buf += next; i += 2; continue; }
581	        quote = null;
582	      }
583	      i += 1;
584	      continue;
585	    }
586	    // Not in a string/identifier: handle comments.
587	    if ((ch === "-" && next === "-") || ch === "#") {
588	      // Line comment to end of line (drop it).
589	      while (i < n && src[i] !== "\n") i += 1;
590	      continue;
591	    }
592	    if (ch === "/" && next === "*") {
593	      i += 2;
594	      while (i < n && !(src[i] === "*" && src[i + 1] === "/")) i += 1;
595	      i += 2;
596	      continue;
597	    }
598	    if (ch === "'" || ch === '"' || ch === "`") { quote = ch as Q; buf += ch; i += 1; continue; }
599	    if (ch === ";") { const t = buf.trim(); if (t) out.push(t); buf = ""; i += 1; continue; }
600	    buf += ch;
601	    i += 1;
602	  }
603	  const tail = buf.trim();
604	  if (tail) out.push(tail);
605	  return out;
606	}
