3	import { useEffect, useState } from "react";
4	import { createHostingDatabase, listHostingDatabases, revealHostingDbPassword, resetHostingDbPassword, type HostingDbView } from "@/lib/actions-hosting";
5	import { DbManager } from "./DbManager";
6	
7	/** Database create/list UI for a hosting account. The database manager is Nxeon DB
8	 *  Studio (the proprietary in-portal manager — see DbManager), which runs all SQL
9	 *  server-side as the account's scoped MySQL user. (The old Adminer drop-in fallback
10	 *  has been removed.) */
11	export function DatabasesPanel({ accountId, username, maxDatabases }: { accountId: string; username: string; maxDatabases: number }) {
12	  const [dbs, setDbs] = useState<HostingDbView[]>([]);
13	  const [dbLabel, setDbLabel] = useState("");
14	  const [dbBusy, setDbBusy] = useState(false);
15	  const [dbErr, setDbErr] = useState("");
16	  const [newDbPassword, setNewDbPassword] = useState<{ name: string; password: string } | null>(null);
17	
18	  useEffect(() => { listHostingDatabases(accountId).then(setDbs).catch(() => {}); }, [accountId]);
19	
20	  async function addDb() {
21	    if (!dbLabel.trim()) return;
22	    setDbBusy(true);
23	    setDbErr("");
24	    try {
25	      const res = await createHostingDatabase(accountId, dbLabel.trim());
26	      if (res.error) setDbErr(res.error);
27	      else {
28	        setNewDbPassword({ name: `${username}_${dbLabel.trim().toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 12) || "db"}`, password: res.password ?? "" });
29	        setDbLabel("");
30	        listHostingDatabases(accountId).then(setDbs).catch(() => {});
31	      }
32	    } finally {
33	      setDbBusy(false);
34	    }
35	  }
36	
37	  if (maxDatabases <= 0) {
38	    return <p className="text-sm text-slate-400">Databases aren’t included on this plan. Upgrade to add MySQL databases.</p>;
39	  }
40	
41	  return (
42	    <div className="space-y-4">
43	      {/* PRIMARY: proprietary in-portal manager (Nxeon DB Studio). */}
44	      <DbManager accountId={accountId} />
45	
46	      <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2">
47	        <div className="mb-1 flex items-center justify-between">
48	          <p className="text-sm font-medium text-slate-300">
49	            Databases <span className="text-xs text-slate-500">({dbs.length}/{maxDatabases})</span>
50	          </p>
51	        </div>
52	        <p className="mb-1 text-[11px] text-slate-500">
53	          Create databases here, then browse and query them in <span className="text-slate-400">Nxeon DB Studio</span> above.
54	        </p>
55	        {dbs.length > 0 && (
56	          <ul className="mb-2 space-y-1 text-xs">
57	            {dbs.map((d) => (
58	              <DbRow key={d.id} db={d} />
59	            ))}
60	          </ul>
61	        )}
62	        {newDbPassword && (
63	          <div className="mb-2 rounded border border-emerald-500/30 bg-emerald-500/10 px-2 py-1.5 text-xs text-emerald-200">
64	            Created <span className="font-mono">{newDbPassword.name}</span> — password (shown once):{" "}
65	            <span className="font-mono">{newDbPassword.password}</span>
66	          </div>
67	        )}
68	        {dbs.length < maxDatabases ? (
69	          <div className="flex items-center gap-2">
70	            <input className="input flex-1 text-xs" placeholder="database name" value={dbLabel} onChange={(e) => setDbLabel(e.target.value)} />
71	            <button className="btn-secondary text-xs" disabled={dbBusy || !dbLabel.trim()} onClick={addDb}>{dbBusy ? "…" : "Create"}</button>
72	          </div>
73	        ) : (
74	          <p className="text-xs text-slate-500">You’ve used all the databases on your plan.</p>
75	        )}
76	        {dbErr && <p className="mt-1 text-xs text-amber-300">{dbErr}</p>}
77	      </div>
78	    </div>
79	  );
80	}
