82	/** One database row with inline "Show password" + "Reset" controls. Mirrors the
83	 *  SFTP reveal UX (HostingTabs) — the password is shown inline in mono, and a reset
84	 *  shows the freshly-generated password once with a "queued" note. */
85	function DbRow({ db }: { db: HostingDbView }) {
86	  const [pw, setPw] = useState<string | null>(null);
87	  const [reset, setReset] = useState<string | null>(null);
88	  const [err, setErr] = useState("");
89	  const [busy, setBusy] = useState<"show" | "reset" | null>(null);
90	
91	  async function show() {
92	    setBusy("show");
93	    setErr("");
94	    try {
95	      const res = await revealHostingDbPassword(db.id);
96	      if (res.error) setErr(res.error);
97	      else setPw(res.password ?? "");
98	    } finally {
99	      setBusy(null);
100	    }
101	  }
102	
103	  async function doReset() {
104	    setBusy("reset");
105	    setErr("");
106	    try {
107	      const res = await resetHostingDbPassword(db.id);
108	      if (res.error) setErr(res.error);
109	      else {
110	        setReset(res.password ?? "");
111	        setPw(res.password ?? "");
112	      }
113	    } finally {
114	      setBusy(null);
115	    }
116	  }
117	
118	  return (
119	    <li className="text-slate-400">
120	      <div className="flex flex-wrap items-center gap-2">
121	        <span className="font-mono text-slate-200">{db.name}</span>
122	        <span className="text-slate-500">user {db.dbUser}</span>
123	        <span className={db.status === "ACTIVE" ? "text-emerald-300" : "text-amber-300"}>{db.status.toLowerCase()}</span>
124	        {pw ? (
125	          <span className="font-mono text-brand-200">{pw}</span>
126	        ) : (
127	          <button type="button" className="text-brand-300 hover:underline disabled:opacity-50" disabled={busy !== null} onClick={show}>
128	            {busy === "show" ? "…" : "Show password"}
129	          </button>
130	        )}
131	        <button type="button" className="text-slate-400 hover:underline disabled:opacity-50" disabled={busy !== null} onClick={doReset}>
132	          {busy === "reset" ? "…" : "Reset"}
133	        </button>
134	      </div>
135	      {reset && (
136	        <p className="mt-0.5 text-[11px] text-emerald-300/90">
137	          New password (shown once): <span className="font-mono text-emerald-200">{reset}</span> — queued, active in a moment.
138	        </p>
139	      )}
140	      {err && <p className="mt-0.5 text-[11px] text-amber-300">{err}</p>}
141	    </li>
142	  );
143	}
