/** Re-queue a FAILED account for the provisioner. Owner or admin. */
export async function retryHostingProvision(id: string): Promise<HostingResult> {
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({ where: { id } });
  if (!a) return { error: "Not found." };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  if (a.status !== "FAILED") return { error: "This account isn’t in a failed state." };
  await db.hostingAccount.update({ where: { id }, data: { status: "PENDING", error: null } });
  revalidatePath("/dashboard/hosting");
  return { ok: true };
}

// ---------- Per-account databases -------------------------------------------

export type HostingDbView = { id: string; name: string; dbUser: string; status: string; password: string | null };

/** Create a scoped database for an account (within the plan's maxDatabases). */
export async function createHostingDatabase(accountId: string, label: string): Promise<{ error?: string; ok?: boolean; password?: string }> {
  const user = await requireUser();
  await assertNotImpersonating();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { id: true, userId: true, status: true, username: true, maxDatabases: true } });
  if (!a) return { error: "Account not found." };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
  // A short, safe suffix keyed off the account username: <user>_<slug>.
  const slug = String(label ?? "").toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 12) || "db";
  const name = `${a.username}_${slug}`.slice(0, 64);
  const dbUser = name.slice(0, 32);
  if (!/^[a-z0-9_]{1,64}$/.test(name)) return { error: "Invalid database name." };
  const password = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
  // Count + create in ONE serializable transaction, so concurrent creates can't
  // both read a stale count and blow past the plan cap (audit 2026-08-01 TOCTOU).
  try {
    await db.$transaction(async (tx) => {
      const n = await tx.hostingDatabase.count({ where: { accountId: a.id, status: { in: ["PENDING", "ACTIVE"] } } });
      if (n >= a.maxDatabases) throw new Error("CAP");
      await tx.hostingDatabase.create({ data: { accountId: a.id, name, dbUser, passwordEnc: encryptSecret(password), status: "PENDING" } });
    }, { isolationLevel: "Serializable" });
  } catch (e) {
    if (e instanceof Error && e.message === "CAP") return { error: `Your plan allows ${a.maxDatabases} database${a.maxDatabases === 1 ? "" : "s"}.` };
    // Serialization conflict (P2034) or the unique(accountId,name) collision.
    return { error: "A database with that name already exists, or the request raced — try again." };
  }
  revalidatePath("/dashboard/hosting");
  // Shown ONCE — the encrypted copy is cleared by the provisioner after it applies it.
  return { ok: true, password };
}

export async function listHostingDatabases(accountId: string): Promise<HostingDbView[]> {
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true } });
  if (!a) return [];
  if (a.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  const rows = await db.hostingDatabase.findMany({ where: { accountId }, orderBy: { createdAt: "desc" } });
